import groovy.json.JsonSlurper

def ff = session.get()
if (!ff) return

def body = ff.getAttribute('invokehttp.response.body')
if (!body) {
  ff = session.putAttribute(ff, 'tomic.token', '')
  session.transfer(ff, REL_SUCCESS)
  return
}

try {
  def json = new JsonSlurper().parseText(body)
  def token = json?.responses?.getAt(0)?.results?.getAt(0)?.token
  ff = session.putAttribute(ff, 'tomic.token', token ? token.toString() : '')
  session.transfer(ff, REL_SUCCESS)
} catch (Exception e) {
  ff = session.putAttribute(ff, 'tomic.token', '')
  ff = session.putAttribute(ff, 'tomic.token.error', e.toString())
  session.transfer(ff, REL_FAILURE)
}

import groovy.json.JsonSlurper

def ff = session.get()
if(!ff) return

// Lee skew desde una property del processor (que referencia Parameter Context)
// Property: token.expiry.skew.seconds = #{token.expiry.skew.seconds}
long skew = 60L
try {
  def ps = context.getProperty('token.expiry.skew.seconds')
  def s = (ps != null && ps.isSet()) ? ps.getValue() : null
  if(s) skew = Long.parseLong(s.toString())
} catch(Exception ignored) {}

// Si no hay cache => pedir login (pero por REL_SUCCESS + atributo)
def cacheStr = ff.getAttribute('tomic.token.cache')
if(!cacheStr) {
  ff = session.putAttribute(ff, 'tomic.token.state', 'LOGIN')
  session.transfer(ff, REL_SUCCESS)
  return
}

def cache
try {
  cache = new JsonSlurper().parseText(cacheStr)
} catch(Exception e) {
  ff = session.putAttribute(ff, 'tomic.token.state', 'LOGIN')
  session.transfer(ff, REL_SUCCESS)
  return
}

def token = cache?.token?.toString()

Long expLong = null
try {
  def exp = cache?.exp
  if(exp != null) expLong = Long.parseLong(exp.toString())
} catch(Exception ignored) {}

long now = (System.currentTimeMillis() / 1000L) as long

if(token && expLong != null && expLong > (now + skew)) {
  ff = session.putAttribute(ff, 'tomic.token', token)
  ff = session.putAttribute(ff, 'tomic.token.exp', expLong.toString())
  ff = session.putAttribute(ff, 'tomic.token.state', 'VALID')
} else {
  ff = session.putAttribute(ff, 'tomic.token.state', 'LOGIN')
}

session.transfer(ff, REL_SUCCESS)

import org.apache.nifi.processor.io.OutputStreamCallback
import groovy.json.*
import java.util.Base64
import java.nio.charset.StandardCharsets

def ff = session.get()
if(!ff) return

def token = ff.getAttribute('tomic.token')
if(!token) { session.transfer(ff, REL_FAILURE); return }

// JWT = header.payload.signature
def parts = token.split('\\.')   // <-- FIX
if(parts.length < 2) { session.transfer(ff, REL_FAILURE); return }

// payload está en Base64URL
def payloadB64 = parts[1]

// padding Base64 (algunos JWT vienen sin '=')
int mod = payloadB64.length() % 4
if(mod == 2) payloadB64 += '=='
else if(mod == 3) payloadB64 += '='
else if(mod != 0) { session.transfer(ff, REL_FAILURE); return }

def payloadJson
try {
  def bytes = Base64.getUrlDecoder().decode(payloadB64) // <-- Base64URL nativo
  payloadJson = new String(bytes, StandardCharsets.UTF_8)
} catch(Exception e) {
  session.transfer(ff, REL_FAILURE); return
}

def payload
try { payload = new JsonSlurper().parseText(payloadJson) }
catch(Exception e) { session.transfer(ff, REL_FAILURE); return }

def exp = payload?.exp
if(exp == null) { session.transfer(ff, REL_FAILURE); return }

long expLong
try { expLong = Long.parseLong(exp.toString()) }
catch(Exception e) { session.transfer(ff, REL_FAILURE); return }

ff = session.putAttribute(ff, 'tomic.token.exp', Long.toString(expLong))

def out = JsonOutput.toJson([token: token, exp: expLong])

ff = session.write(ff, { os ->
  os.write(out.getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(ff, REL_SUCCESS)

import org.apache.nifi.processor.io.InputStreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

// -------------------- CONFIG --------------------
// Puedes definir una Dynamic Property en el processor: batch.size = 2000 (o lo que quieras)
int DEFAULT_BATCH_SIZE = 2000
int batchSize
try {
    def p = context.getProperty('batch.size')
    def v = p ? p.evaluateAttributeExpressions(session.get())?.value : null
    batchSize = (v ? Integer.parseInt(v.trim()) : DEFAULT_BATCH_SIZE)
} catch (Exception ignore) {
    batchSize = DEFAULT_BATCH_SIZE
}
if (batchSize <= 0) batchSize = DEFAULT_BATCH_SIZE

def ff = session.get()
if (!ff) return

// ---------- Read content ----------
def txt = ''
session.read(ff, { inp ->
    txt = inp.getText(StandardCharsets.UTF_8.name())
} as InputStreamCallback)

// ---------- Parse JSON ----------
def ev
try {
    ev = new JsonSlurper().parseText(txt)
} catch (Exception e) {
    log.error("JSON inválido", e)
    session.transfer(ff, REL_FAILURE)
    return
}

// Soporta payloads tipo lista: [ {...} ]
if (ev instanceof List) {
    if (ev.isEmpty()) { session.transfer(ff, REL_FAILURE); return }
    ev = ev[0]
}

// ---------- Extract identifiers ----------
def uploadId   = (ff.getAttribute('uploadId') ?: ev.uploadId)?.toString()
def agentId    = (ff.getAttribute('agentId')  ?: ev.agentId )?.toString()
def runId      = (ff.getAttribute('runId')    ?: ev.runId   )?.toString()
def s3Bucket   = (ff.getAttribute('s3Bucket') ?: ev.s3Bucket)?.toString()
def sourceName = (ff.getAttribute('sourceName') ?: ev.sourceName ?: ev.folder?.source?.name)?.toString()

if (!uploadId || !agentId || !runId || !sourceName || !ev?.folder) {
    log.error("Faltan campos requeridos: uploadId={}, agentId={}, runId={}, sourceName={}, folder={}",
            [uploadId, agentId, runId, sourceName, ev?.folder] as Object[])
    session.transfer(ff, REL_FAILURE)
    return
}

// Nueva estructura runRoot: agent/sourceName/agentId/runId
String runRoot   = "agent/${sourceName}/${agentId}/${runId}".toString()
String runTagStr = "run_${runId}".toString()

// ---------- Helpers ----------
def extractSampleId = { String name ->
    if (!name) return null
    def m = (name =~ /^(.+?)_S\d+_/)
    if (m.find()) return m.group(1)
    def idx = name.indexOf('_')
    if (idx > 0) return name.substring(0, idx)
    return null
}

def parseS3 = { String uri ->
    if (!uri) return null
    def m = (uri =~ /^s3:\/\/([^\/]+)\/(.+)$/)
    if (!m.find()) return null
    return [bucket: m.group(1), key: m.group(2)]
}

def normDirKey = { String k ->
    if (!k) return k
    k = k.replace('\\','/')
    while (k.endsWith("/")) k = k.substring(0, k.length() - 1)
    return k
}

def addParentDirsFromPath = { String fullPath, def addDirFn ->
    if (!fullPath) return
    fullPath = fullPath.replace('\\','/')
    def parts = fullPath.split('/')
    if (parts.size() <= 1) return
    def cur = ''
    for (int i = 0; i < parts.size() - 1; i++) {
        cur = (i == 0) ? parts[i] : (cur + '/' + parts[i])
        if (cur) addDirFn(cur)
    }
}

// Propagar tags de sample a todos los directorios padre dentro de runRoot
def addSampleToDirChainUnderRun = { String fileKey, String sid, def dirSampleTagsMap ->
    if (!sid || !fileKey) return
    fileKey = fileKey.replace('\\','/')
    if (!fileKey.startsWith(runRoot + "/")) return

    int last = fileKey.lastIndexOf('/')
    if (last <= 0) return

    def parentDir = fileKey.substring(0, last)
    def current = parentDir
    while (current != runRoot && current.length() > runRoot.length()) {
        dirSampleTagsMap[current.toString()].add("sample_${sid}".toString())
        int lastSlash = current.lastIndexOf('/')
        if (lastSlash < 0) break
        current = current.substring(0, lastSlash)
    }
}

// ---------- Determine root folder key ----------
String rootKey = runRoot
String rootBucket = s3Bucket

def rootUrl = ev.folder?.url?.toString()
if (rootUrl) {
    def p = parseS3(rootUrl)
    if (p) {
        rootBucket = (p.bucket?.toString() ?: rootBucket)
        rootKey    = normDirKey(p.key?.toString() ?: rootKey)?.toString()
    }
}

// -------------------- PASS 1: collect dirs, dirSampleTags, fileCount --------------------
def dirs = new LinkedHashSet<String>()
def addDir = { def d ->
    if (d == null) return
    String s = d.toString()
    if (s) dirs.add(s)
}

// tags por directorio (sample propagation)
def dirSampleTags = [:].withDefault { new LinkedHashSet<String>() }

long fileCount = 0L

// base dirs
addDir('agent')
addDir("agent/${sourceName}".toString())
addDir("agent/${sourceName}/${agentId}".toString())
addDir(runRoot)

// Walk pass1
def walk1
walk1 = { folderNode, String curDirKey, String curBucket ->
    if (!folderNode) return

    def fUrl = folderNode?.url?.toString()
    if (fUrl) {
        def p = parseS3(fUrl)
        if (p) {
            curBucket = (p.bucket?.toString() ?: curBucket)
            curDirKey = normDirKey(p.key?.toString() ?: curDirKey)?.toString()
        }
    }

    if (curDirKey) {
        curDirKey = normDirKey(curDirKey)?.toString()
        addDir(curDirKey)
        addParentDirsFromPath(curDirKey + "/dummy", addDir)
    }

    // files
    (folderNode?.files ?: []).each { fref ->
        def fname = fref?.name?.toString()
        if (!fname) return

        def fileUrl = fref?.url?.toString()
        String keyPath
        String bucket = (curBucket ?: s3Bucket)

        if (fileUrl) {
            def p = parseS3(fileUrl)
            if (!p) return
            bucket  = (p.bucket?.toString() ?: bucket)
            keyPath = p.key?.toString()
        } else {
            def base = curDirKey ?: runRoot
            base = normDirKey(base?.toString())?.toString()
            keyPath = "${base}/${fname}".toString()
        }

        keyPath = normDirKey(keyPath)?.toString()

        fileCount++
        addParentDirsFromPath(keyPath, addDir)

        def sid = extractSampleId(fname)
        if (sid) addSampleToDirChainUnderRun(keyPath, sid, dirSampleTags)
    }

    // subfolders
    (folderNode?.folders ?: []).each { sub ->
        def subName = sub?.name?.toString()
        if (!subName) return

        def subUrl = sub?.url?.toString()
        String subDirKey
        String subBucket = (curBucket ?: s3Bucket)

        if (subUrl) {
            def p = parseS3(subUrl)
            if (p) {
                subBucket = (p.bucket?.toString() ?: subBucket)
                subDirKey = normDirKey(p.key?.toString())?.toString()
            } else {
                subDirKey = "${normDirKey(curDirKey?.toString())}/${subName}".toString()
            }
        } else {
            def base = curDirKey ?: runRoot
            subDirKey = "${normDirKey(base?.toString())}/${subName}".toString()
        }

        addDir(subDirKey)
        walk1(sub, subDirKey, subBucket)
    }
}

walk1(ev.folder, rootKey, rootBucket)

// sort dirs
def dirList = dirs.toList().collect { it.toString() }.unique().sort { a, b ->
    def da = a.count('/')
    def db = b.count('/')
    if (da != db) return da <=> db
    return a <=> b
}

String dirCountStr  = String.valueOf(dirList.size())
String fileCountStr = String.valueOf(fileCount)

// -------------------- Continuation state from attributes --------------------
String phase = (ff.getAttribute('emit.phase') ?: 'DIR').toString().toUpperCase()
int dirIndex = 0
long fileIndex = 0L
try { dirIndex = Integer.parseInt((ff.getAttribute('emit.dir.index') ?: '0').toString()) } catch (ignore) { dirIndex = 0 }
try { fileIndex = Long.parseLong((ff.getAttribute('emit.file.index') ?: '0').toString()) } catch (ignore) { fileIndex = 0L }
if (dirIndex < 0) dirIndex = 0
if (fileIndex < 0) fileIndex = 0L

// ---------- Common attrs for children ----------
def commonAttrs = [
        'uploadId'   : uploadId,
        'dir_count'  : dirCountStr,
        'file_count' : fileCountStr,
        'sourceName' : sourceName,
        'agentId'    : agentId,
        'runId'      : runId
]

// (Opcional) trazabilidad
def parentUuid = ff.getAttribute('uuid')

// -------------------- Emit in batches --------------------
int emittedTotal = 0

// ---- Emit DIR tasks (batchable) ----
while (phase == 'DIR' && dirIndex < dirList.size() && emittedTotal < batchSize) {
    String d = dirList[dirIndex]
    dirIndex++

    def tags = []
    if (d == runRoot) {
        tags = [runTagStr]
    } else if (d.startsWith(runRoot + "/")) {
        tags = [runTagStr]
        def sampleTags = dirSampleTags[d.toString()]
        if (sampleTags) tags.addAll(sampleTags.collect { it.toString() })
    }
    tags = tags.unique()

    def dff = session.create() // NO session.create(ff)
    dff = session.putAllAttributes(dff, commonAttrs)
    dff = session.putAttribute(dff, 'task.type', 'DIR')
    dff = session.putAttribute(dff, 'tomic.dir.path', d)
    dff = session.putAttribute(dff, 'tomic.dir.tags.json', JsonOutput.toJson(tags))
    if (parentUuid) dff = session.putAttribute(dff, 'parent.uuid', parentUuid)

    session.transfer(dff, REL_SUCCESS)
    emittedTotal++
}

if (phase == 'DIR' && dirIndex >= dirList.size()) {
    phase = 'FILE'
    if (fileIndex < 0L) fileIndex = 0L
}

// ---- Emit FILE tasks (batchable, without building files[] in memory) ----
def walkEmitFiles
walkEmitFiles = { folderNode, String curDirKey, String curBucket,
                  long startIdx, int limit,
                  long[] globalIdxRef, int[] emittedRef ->

    if (!folderNode) return false

    def fUrl = folderNode?.url?.toString()
    if (fUrl) {
        def p = parseS3(fUrl)
        if (p) {
            curBucket = (p.bucket?.toString() ?: curBucket)
            curDirKey = normDirKey(p.key?.toString() ?: curDirKey)?.toString()
        }
    }

    // files
    for (def fref : (folderNode?.files ?: [])) {
        def fname = fref?.name?.toString()
        if (!fname) {
            // aun así no incrementamos índice si no hay nombre (no cuenta como file real)
            continue
        }

        long idx = globalIdxRef[0]
        def fileUrl = fref?.url?.toString()

        String keyPath
        String uri
        String bucket = (curBucket ?: s3Bucket)

        if (fileUrl) {
            def p = parseS3(fileUrl)
            if (!p) {
                globalIdxRef[0] = idx + 1
                // cuenta igual como file? en pass1 lo contábamos sólo si fname existía; aquí también
                // si url no parseable, lo saltamos pero sí avanzamos el índice para consistencia
                continue
            }
            bucket  = (p.bucket?.toString() ?: bucket)
            keyPath = p.key?.toString()
            uri     = fileUrl
        } else {
            def base = curDirKey ?: runRoot
            base = normDirKey(base?.toString())?.toString()
            keyPath = "${base}/${fname}".toString()
            uri = "s3://${bucket}/${keyPath}"
        }

        keyPath = normDirKey(keyPath)?.toString()

        // Emit only if within [startIdx, startIdx+limit)
        if (idx >= startIdx && emittedRef[0] < limit) {
            def sid = extractSampleId(fname)

            def tags = new ArrayList<String>(2)
            tags.add(runTagStr)
            if (sid) tags.add("sample_${sid}".toString())

            def fff = session.create() // NO session.create(ff)
            fff = session.putAllAttributes(fff, commonAttrs)
            fff = session.putAttribute(fff, 'task.type', 'FILE')
            fff = session.putAttribute(fff, 'tomic.file.path', keyPath)
            fff = session.putAttribute(fff, 'tomic.file.uri',  uri.toString())
            fff = session.putAttribute(fff, 'tomic.file.ref',  keyPath.replace('/' as char, ':' as char))
            fff = session.putAttribute(fff, 'tomic.tags.json', JsonOutput.toJson(tags))
            if (parentUuid) fff = session.putAttribute(fff, 'parent.uuid', parentUuid)

            session.transfer(fff, REL_SUCCESS)
            emittedRef[0]++
        }

        globalIdxRef[0] = idx + 1

        if (emittedRef[0] >= limit) return true
    }

    // subfolders
    for (def sub : (folderNode?.folders ?: [])) {
        def subName = sub?.name?.toString()
        if (!subName) continue

        def subUrl = sub?.url?.toString()

        String subDirKey
        String subBucket = (curBucket ?: s3Bucket)

        if (subUrl) {
            def p = parseS3(subUrl)
            if (p) {
                subBucket = (p.bucket?.toString() ?: subBucket)
                subDirKey = normDirKey(p.key?.toString())?.toString()
            } else {
                subDirKey = "${normDirKey(curDirKey?.toString())}/${subName}".toString()
            }
        } else {
            def base = curDirKey ?: runRoot
            subDirKey = "${normDirKey(base?.toString())}/${subName}".toString()
        }

        if (walkEmitFiles(sub, subDirKey, subBucket, startIdx, limit, globalIdxRef, emittedRef)) {
            return true
        }
    }

    return false
}

if (phase == 'FILE' && emittedTotal < batchSize && fileIndex < fileCount) {
    int remaining = batchSize - emittedTotal
    long[] globalIdxRef = [0L] as long[]
    int[] emittedRef = [0] as int[]

    walkEmitFiles(ev.folder, rootKey, rootBucket, fileIndex, remaining, globalIdxRef, emittedRef)

    emittedTotal += emittedRef[0]
    fileIndex += emittedRef[0]
}

// -------------------- Decide whether to continue --------------------
boolean done = (phase == 'FILE' && fileIndex >= fileCount)

// NO quiero el atributo folder => si venía como atributo, lo quitamos del CONTROL para que no se re-escriba
if (!done) {
    if (ff.getAttribute('folder') != null) {
        ff = session.removeAttribute(ff, 'folder')
    }

    ff = session.putAttribute(ff, 'task.type', 'CONTROL')         // para rutearlo de vuelta
    ff = session.putAttribute(ff, 'emit.phase', phase)
    ff = session.putAttribute(ff, 'emit.dir.index', String.valueOf(dirIndex))
    ff = session.putAttribute(ff, 'emit.file.index', String.valueOf(fileIndex))
    ff = session.putAttribute(ff, 'emit.batch.size', String.valueOf(batchSize))
    ff = session.putAttribute(ff, 'emit.last.emitted', String.valueOf(emittedTotal))

    // útil (pequeño)
    ff = session.putAttribute(ff, 'uploadId', uploadId)
    ff = session.putAttribute(ff, 'dir_count', dirCountStr)
    ff = session.putAttribute(ff, 'file_count', fileCountStr)
    ff = session.putAttribute(ff, 'sourceName', sourceName)

    // Evita loop apretado si lo reinyectas inmediatamente
    ff = session.penalize(ff)

    session.transfer(ff, REL_SUCCESS)
} else {
    session.remove(ff)
}

import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import groovy.json.*
import java.nio.charset.StandardCharsets

def ff = session.get()
if(!ff) return

// Lee la property del processor (que a su vez usa #{dlq.include.payload})
def includePayload = (context.getProperty('dlq.include.payload')?.getValue() ?: 'false')
        .equalsIgnoreCase('true')

def payloadText = ''
session.read(ff, { inp ->
  payloadText = inp.getText(StandardCharsets.UTF_8.name())
} as InputStreamCallback)

def attrs = new LinkedHashMap<String,String>()
ff.getAttributes().each { k,v -> attrs[k]=v }

def outObj = [
  ts: System.currentTimeMillis(),
  error: [
    httpStatus: attrs['invokehttp.status.code'],
    httpBody: attrs['invokehttp.response.body']
  ],
  attributes: attrs
]

if(includePayload && payloadText) {
  try { outObj.payload = new JsonSlurper().parseText(payloadText) }
  catch(Exception e) { outObj.payload = payloadText }
}

def out = JsonOutput.toJson(outObj)

ff = session.write(ff, { os ->
  os.write(out.getBytes(StandardCharsets.UTF_8))
} as OutputStreamCallback)

session.transfer(ff, REL_SUCCESS)

import org.apache.nifi.processor.io.InputStreamCallback
import org.apache.nifi.processor.io.OutputStreamCallback
import groovy.json.JsonSlurper
import groovy.json.JsonOutput
import java.nio.charset.StandardCharsets

def ff = session.get()
if (!ff) return

def text = ''
session.read(ff, { inputStream ->
    text = inputStream.getText(StandardCharsets.UTF_8.name())
} as InputStreamCallback)

def obj
try {
    obj = new JsonSlurper().parseText(text)
} catch (Exception e) {
    log.error("JSON inválido en el FlowFile {}", [ff] as Object[], e)
    session.transfer(ff, REL_FAILURE)
    return
}

if (obj instanceof List) {
    if (obj.isEmpty()) {
        session.transfer(ff, REL_FAILURE)
        return
    }
    obj = obj[0]
}

